export function icon(name, extraClass = '', size = 20) {
  const svg = SVG_ICONS[name] || SVG_ICONS.Check;
  if (!extraClass && !size) return svg;
  
  // Inject class and dimensions
  let modified = svg.replace('<svg ', `<svg class="ff-icon ${extraClass}" width="${size}" height="${size}" `);
  return modified;
}
